/* Each property here is one that Kumu's property reference gives the selector's type (element,
   connection or loop: its table marks which type takes which property); check a new one there
   before writing it, and see it work in a test import. */

@controls {
  bottom-left {
    showcase {
      as: buttons;
      /* strict shows only what an option selects: normal adds the links among its elements and
         loose their neighbours, which are not the loop */
      mode: strict;

      /* build.py replaces the next line with an option per named loop */
      option {
        label: "R1 Salty soil takes in less rain";
        selector: *:loop(["label"="R1 Salty soil takes in less rain"]), #background;
