@settings {
  layout: static;
  theme: light;
  background-color: #FFFFFF;
  culling: off;
}

/* ---------- Elements: the page's look, values from draw.py ---------- */
/* each box's fill (its SETS domain's tint, draw.py's TINT), width and height are rules
   build.py generates below this view in docs/project.json. Kumu draws text at about 0.6 of
   its font-size in map units, so each font-size is the page's x 1.5, to fill the box
   draw.py fits */
/* pill: Kumu's rectangle with rounded corners */
element {
  shape: pill;
  border-color: #444444;
  border-width: 1.5;
  font-size: 42;
  font-weight: normal;
  font-color: #000000;
  text-align: center;
  /* build.py puts a double space where the page breaks a label's line */
  text-overflow: manual;
  shadow-visibility: hidden;
}

["element type"="stock"] {
  shape: rectangle;
}

/* Kumu has no dashed border: a constant gets an italic label */
["element type"="constant"] {
  font-style: italic;
}

["adaptive practice"="yes"] {
  border-width: 5;
}

/* ---------- Regions: the page's two subsystem regions as a background image ---------- */
/* the rule of Kumu's images guide (docs.kumu.io/guides/images.html); build.py adds the element,
   pinned at the centre of the regions' frame, and its width and height, the frame's. A showcase
   fades all it does not select, so every showcase option above selects #background too */
#background {
  image-url: url(https://jordyzuidam2003-bot.github.io/zeeland-cld/regions.svg);
  layer: background;
  shape: rectangle;
  color: transparent;
  image-size: contain;
  image-resolution: original;
  label-visibility: none;
  border-width: 0;
}

/* ---------- Links: one width, the sign's colour ---------- */
/* (no global curvature: each link keeps its own curve from the map) */
connection {
  size: 2.5;
  style: solid;
  arrow-visibility: visible;
  label: none;
  font-size: 63;
  font-weight: bold;
}

["polarity"="positive"] {
  color: #2166AC;
  font-color: #2166AC;
}

["polarity"="negative"] {
  color: #B2182B;
  font-color: #B2182B;
}

/* ---------- Loops: Kumu's named loops, no label on the map ---------- */
/* the full drawing has no loop marks (the router's layout decision); Kumu's property reference
   gives loops `label`, not `label-visibility` */
loop {
  label: none;
}

